# Dangerous constructs inside a <style> ... </style> block.
_CSS_EXPRESSION_RE = re.compile(r"expression\s*\(.*?\)", re.I | re.S)
_CSS_URL_JS_RE = re.compile(
    r"url\s*\(\s*[\'\" ]*\s*(?:javascript|vbscript)\s*:[^)]*\)", re.I | re.S
)
_CSS_IMPORT_JS_RE = re.compile(
    r"@import\s+(?:url\s*\(\s*)?[\'\" ]*(?:javascript|vbscript)\s*:[^;)\"']*",
    re.I | re.S,
)"}

