    return css","new_string":"def _matching_paren(text, open_pos):
    """Given text[open_pos] == '(', return the index just after its match."""
    depth = 0
    for i in range(open_pos, len(text)):
        if text[i] == "(":
            depth += 1
        elif text[i] == ")":
            depth -= 1
            if depth == 0:
                return i + 1
    return len(text)


def _sanitize_css(css):
    """Remove JavaScript-bearing constructs from a <style> block."""
    out = []
    i = 0
    n = len(css)

    while i < n:
        m = _CSS_IMPORT_RE.match(css, i)
        if m:
            end = i
            while end < n and css[end] not in ";\n":
                end += 1
            statement = css[i:end]
            if _CSS_JS_URL_RE.search(statement):
                i = end
                if i < n and css[i] == ";":
                    i += 1
                continue
            out.append(css[i])
            i += 1
            continue

        m = _CSS_EXPRESSION_RE.match(css, i)
        if m:
            open_pos = css.find("(", i)
            if open_pos != -1:
                i = _matching_paren(css, open_pos)
                continue
            out.append(css[i])
            i += 1
            continue

        m = _CSS_URL_RE.match(css, i)
        if m:
            open_pos = css.find("(", i)
            if open_pos != -1:
                end = _matching_paren(css, open_pos)
                content = css[open_pos + 1 : end - 1]
                if _CSS_JS_URL_RE.search(content):
                    out.append("url()")
                else:
                    out.append(css[i:end])
                i = end
                continue
            out.append(css[i])
            i += 1
            continue

        out.append(css[i])
        i += 1

    return "".join(out)"}

